import React, { memo, useState, useEffect, useMemo, useCallback } from 'react';
import { Handle, Position } from 'reactflow';
import { JsonForms } from '@jsonforms/react';
import { useWorkflowNodes } from '../context';
import { workflowNodeRenderers } from '../jsonFormsRenderers';
import { TbRefresh, TbSend } from 'react-icons/tb';
import { VscDebugDisconnect } from 'react-icons/vsc';
import { Button } from '@jet-admin/ui';

const ERROR_HANDLING_OPTIONS = {
  FAIL_WORKFLOW: 'fail_workflow',
  CONTINUE: 'continue',
};

// ── Configurator (side panel form) ──────────────────────────────────────────

export const ConnectorPushNodeConfigurator = ({ data, onChange, nodeId }) => {
  const { datasources, strings, onRefreshDatasources, workflowNodes, workflowEdges, workflowInputArgs } = useWorkflowNodes();

  const [formData, setFormData] = useState({
    title: data?.title || 'Connector Push',
    description: data?.description || '',
    datasourceID: data?.datasourceID || '',
    input: data?.input || {},
    outputVariable: data?.outputVariable || 'pushResult',
    timeoutSeconds: data?.timeoutSeconds ?? 300,
    errorHandling: data?.errorHandling || ERROR_HANDLING_OPTIONS.FAIL_WORKFLOW,
    isDisabled: data?.isDisabled ?? false,
  });

  useEffect(() => {
    if (data) {
      setFormData({
        title: data.title || 'Connector Push',
        description: data.description || '',
        datasourceID: data.datasourceID || '',
        input: data.input || {},
        outputVariable: data.outputVariable || 'pushResult',
        timeoutSeconds: data.timeoutSeconds ?? 300,
        errorHandling: data.errorHandling || ERROR_HANDLING_OPTIONS.FAIL_WORKFLOW,
        isDisabled: data.isDisabled ?? false,
      });
    }
  }, [data]);

  // Build a dropdown enum from real datasources — same pattern as DataQueryNode
  const datasourceEnums = useMemo(() => {
    return datasources?.map(ds => String(ds.datasourceID)) || [''];
  }, [datasources]);

  const datasourceEnumLabels = useMemo(() => {
    return datasources?.reduce((acc, ds) => {
      acc[String(ds.datasourceID)] = `${ds.datasourceTitle} (${ds.datasourceType})`;
      return acc;
    }, {}) || {};
  }, [datasources]);

  const selectedDatasource = useMemo(() => {
    return datasources?.find(ds => String(ds.datasourceID) === String(formData.datasourceID)) || null;
  }, [datasources, formData.datasourceID]);

  const schema = useMemo(() => ({
    type: 'object',
    properties: {
      title: { type: 'string', title: 'Node Title' },
      description: { type: 'string', title: 'Description' },
      datasourceID: {
        type: 'string',
        title: 'Datasource',
        enum: datasourceEnums.length > 0 ? datasourceEnums : [''],
      },
      input: {
        type: 'object',
        title: 'Payload / Parameters',
      },
      outputVariable: {
        type: 'string',
        title: 'Output Variable Name',
        pattern: '^[a-zA-Z_][a-zA-Z0-9_]*$',
        default: 'pushResult',
      },
      timeoutSeconds: {
        type: 'integer',
        title: 'Timeout (seconds)',
        minimum: 1,
        maximum: 3600,
        default: 300,
      },
      errorHandling: {
        type: 'string',
        title: 'Error Behavior',
        enum: Object.values(ERROR_HANDLING_OPTIONS),
      },
      isDisabled: {
        type: 'boolean',
        title: 'Skip this node',
        default: false,
      },
    },
    required: ['datasourceID'],
  }), [datasourceEnums]);

  const uischema = useMemo(() => ({
    type: 'Categorization',
    elements: [
      {
        type: 'Category',
        label: 'General',
        elements: [
          { type: 'Control', scope: '#/properties/title', options: { placeholder: 'e.g., Send Slack Message' } },
          { type: 'Control', scope: '#/properties/description', options: { multi: true, rows: 2, placeholder: 'Describe what this connector push does...' } },
          {
            type: 'Control', scope: '#/properties/datasourceID', options: {
              placeholder: 'Select a datasource',
              enumLabels: datasourceEnumLabels,
              showRefreshButton: !!onRefreshDatasources,
              onRefresh: onRefreshDatasources,
            },
          },
          {
            type: 'Control', scope: '#/properties/input',
            options: {
              isDynamicArgs: true,
              args: [],
              workflowNodes,
              workflowEdges,
              workflowInputArgs,
              currentNodeId: nodeId,
            },
          },
        ],
      },
      {
        type: 'Category',
        label: 'Output',
        elements: [
          { type: 'Control', scope: '#/properties/outputVariable', options: { placeholder: 'e.g., pushResult' } },
        ],
      },
      {
        type: 'Category',
        label: 'Advanced',
        elements: [
          { type: 'Control', scope: '#/properties/timeoutSeconds' },
          {
            type: 'Control', scope: '#/properties/errorHandling', options: {
              enumLabels: {
                [ERROR_HANDLING_OPTIONS.FAIL_WORKFLOW]: 'Fail Workflow',
                [ERROR_HANDLING_OPTIONS.CONTINUE]: 'Continue (ignore error)',
              },
            },
          },
          { type: 'Control', scope: '#/properties/isDisabled' },
        ],
      },
    ],
  }), [datasourceEnumLabels, workflowNodes, workflowEdges, workflowInputArgs, nodeId, onRefreshDatasources]);

  const handleFormChange = useCallback(({ data: newData }) => { setFormData(newData); }, []);
  const handleSave = useCallback(() => { onChange(formData); }, [onChange, formData]);

  return (
    <div className="w-full space-y-3">
      <JsonForms schema={schema} uischema={uischema} data={formData} renderers={workflowNodeRenderers} onChange={handleFormChange} />

      {/* Selected datasource info */}
      {selectedDatasource && (
        <div className="rounded-lg border border-purple-200 bg-purple-50 p-2.5 text-[10px] text-purple-800">
          <div className="font-semibold text-xs">✅ {selectedDatasource.datasourceTitle}</div>
          <div className="mt-0.5 text-purple-600">Type: {selectedDatasource.datasourceType}</div>
        </div>
      )}

      {/* Help callout */}
      <div className="rounded-lg border border-border bg-muted/30 p-3 text-[10px] text-muted-foreground space-y-2">
        <div className="font-semibold text-xs text-foreground">📤 Connector Push</div>
        <div>
          <span className="font-medium text-foreground">How it works:</span>
          <div className="ml-3 mt-0.5 space-y-0.5">
            <div>Sends data to a datasource via the Integration Fabric.</div>
            <div>Use for: DB inserts, API calls, Kafka produce, Slack messages, etc.</div>
          </div>
        </div>
        <div>
          <span className="font-medium text-foreground">Payload Format:</span>
          <div className="ml-3 mt-0.5 font-mono text-[9px] space-y-0.5">
            <div><code className="bg-background px-1 rounded border border-border">{'{{ctx.connectorResult}}'}</code> → forward previous result</div>
            <div><code className="bg-background px-1 rounded border border-border">{'{{ctx.input.message}}'}</code> → from workflow input</div>
          </div>
        </div>
      </div>

      <Button type="button" onClick={handleSave} className="w-full">
        Save
      </Button>
    </div>
  );
};

// ── Canvas card ─────────────────────────────────────────────────────────────

export const ConnectorPushNode = memo(({ id, data, isConnectable }) => {
  const { nodeExecutionStatus, datasources } = useWorkflowNodes();
  const executionStatus = nodeExecutionStatus?.[id] || 'idle';
  const isDisabled = data?.isDisabled ?? false;

  // Resolve datasource title for display
  const datasourceLabel = useMemo(() => {
    if (!data?.datasourceID) return 'Select Datasource';
    const ds = datasources?.find(d => String(d.datasourceID) === String(data.datasourceID));
    return ds ? `${ds.datasourceTitle}` : 'Unknown Datasource';
  }, [data?.datasourceID, datasources]);

  const datasourceType = useMemo(() => {
    if (!data?.datasourceID) return null;
    const ds = datasources?.find(d => String(d.datasourceID) === String(data.datasourceID));
    return ds?.datasourceType || null;
  }, [data?.datasourceID, datasources]);

  const getStatusStyles = () => {
    switch (executionStatus) {
      case 'running': return 'border-purple-400 ring-2 ring-purple-300 ring-opacity-50 animate-pulse';
      case 'completed': return 'border-green-400 ring-2 ring-green-300 ring-opacity-50';
      case 'failed': return 'border-red-400 ring-2 ring-red-300 ring-opacity-50';
      case 'skipped': return 'border-orange-300 opacity-60';
      default: return 'border-slate-200 hover:border-purple-400 hover:shadow-md';
    }
  };

  const StatusIndicator = () => {
    if (executionStatus === 'running') return (
      <div className="absolute -top-2 -right-2 w-5 h-5 bg-purple-500 rounded-full flex items-center justify-center animate-spin">
        <TbRefresh className="w-3 h-3 text-white" />
      </div>
    );
    if (executionStatus === 'completed') return (
      <div className="absolute -top-2 -right-2 w-5 h-5 bg-green-500 rounded-full flex items-center justify-center">
        <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
        </svg>
      </div>
    );
    if (executionStatus === 'failed') return (
      <div className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center">
        <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
        </svg>
      </div>
    );
    return null;
  };

  return (
    <div className={`relative bg-white border rounded min-w-[340px] max-w-[400px] transition-all duration-150 ${isDisabled ? 'border-slate-200 opacity-50' : getStatusStyles()} ${!data.datasourceID ? '!border-red-400 !bg-red-50' : ''}`}>
      <StatusIndicator />
      <div className="flex items-stretch">
        <div style={{ borderTopLeftRadius: '0.25rem', borderBottomLeftRadius: '0.25rem' }}
          className={`flex flex-col items-center justify-center px-3 py-3 border-r ${isDisabled ? 'bg-slate-50 border-slate-100' :
              executionStatus === 'running' ? 'bg-purple-100 border-purple-200' :
                executionStatus === 'completed' ? 'bg-green-50 border-green-100' :
                  executionStatus === 'failed' ? 'bg-red-50 border-red-100' :
                  'bg-purple-50 border-purple-100'
            }`}
        >
          <TbSend className={`w-5 h-5 ${isDisabled ? 'text-slate-400' : executionStatus === 'running' ? 'text-purple-600' : executionStatus === 'completed' ? 'text-green-600' : executionStatus === 'failed' ? 'text-red-600' : 'text-purple-500'}`} />
        </div>
        <div className="flex-1 px-3 py-2 min-w-0">
          <div className="flex items-center justify-between gap-2">
            <span className={`text-xs font-semibold truncate ${isDisabled ? 'text-slate-400 line-through' : 'text-slate-700'}`}>{data?.title || 'Connector Push'}</span>
            {isDisabled && (
              <span className="inline-flex items-center gap-1 text-[9px] font-medium text-orange-600 bg-orange-100 px-1.5 py-0.5 rounded border border-orange-200">
                <VscDebugDisconnect className="w-2.5 h-2.5" />Skip
              </span>
            )}
          </div>
          <div className={`text-sm truncate mt-0.5 ${isDisabled ? 'text-slate-300' : 'text-slate-500'}`}>
            {datasourceLabel.length > 24 ? `${datasourceLabel.substring(0, 24)}...` : datasourceLabel}
          </div>
          {datasourceType && (
            <div className={`text-[9px] mt-0.5 font-medium ${isDisabled ? 'text-slate-300' : 'text-purple-500'}`}>
              {datasourceType}
            </div>
          )}
        </div>
        <div className="flex flex-col items-center justify-center px-2 border-l border-slate-100">
          <div className={`w-2 h-2 rounded-full mb-1 ${isDisabled ? 'bg-slate-300' : 'bg-green-400'}`} title="Success" />
          <div className={`w-2 h-2 rounded-full ${isDisabled ? 'bg-slate-300' : 'bg-red-400'}`} title="Error" />
        </div>
      </div>
      <Handle type="target" position={Position.Top} isConnectable={isConnectable} style={{ width: '10px', height: '10px', backgroundColor: isDisabled ? '#cbd5e1' : '#a855f7', border: 'none', top: '-5px' }} />
      <Handle type="source" position={Position.Bottom} id="success" isConnectable={isConnectable} style={{ left: '35%', width: '10px', height: '10px', backgroundColor: isDisabled ? '#cbd5e1' : '#22c55e', border: 'none', bottom: '-5px' }} />
      <Handle type="source" position={Position.Bottom} id="error" isConnectable={isConnectable} style={{ left: '65%', width: '10px', height: '10px', backgroundColor: isDisabled ? '#cbd5e1' : '#ef4444', border: 'none', bottom: '-5px' }} />
    </div>
  );
});
